import{defaults,valueCompany,validateSnapshot,eligibleSnapshots,lockExperiment,evaluateHistory,normalizeCompany,terminalValue}from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Appearance changes presentation only; research cases and model inputs are untouched.
const themeNames=['forest','slate','midnight','sand','plum','ocean'];
function setTheme(theme,persist=false){
 if(!themeNames.includes(theme))theme='forest';
 document.documentElement.dataset.theme=theme;
 const themeLabel=document.querySelector('#current-theme-name');if(themeLabel)themeLabel.textContent={forest:'Paper & Forest',slate:'Slate & Blue',midnight:'Midnight',sand:'Sand & Terracotta',plum:'Plum & Rose',ocean:'Ocean & Teal'}[theme];
 document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===theme)));
 document.querySelector('meta[name="theme-color"]').content={forest:'#183b30',slate:'#172b4a',midnight:'#111a29',sand:'#633b2c',plum:'#402642',ocean:'#123f49'}[theme];
 if(persist)try{localStorage.setItem('valuation-lab-theme',theme)}catch{toast('Theme changed for this visit. Browser storage is unavailable.')}
}
setTheme(document.documentElement.dataset.theme);
document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>setTheme(b.dataset.themeChoice,true));
window.addEventListener('storage',e=>{if(e.key==='valuation-lab-theme')setTheme(e.newValue)});
const n=(v,d=1)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';const pct=v=>n(v*100,1)+'%';
const lesson={ticker:'LESSON',name:'Illustrative operating business',currency:'USD',units:'millions',periodEnd:'2022-12-31',filedAt:'2023-02-01',availableFrom:'2023-02-02',sourceUrl:'https://pages.stern.nyu.edu/~adamodar/',revenue:1000,ebit:200,cash:100,debt:200,shares:100,shareBasis:'hypothetical shares',notes:'Invented teaching inputs. Not a real company or market estimate.'};
const popular=[['NVDA','NVIDIA'],['AAPL','Apple'],['MSFT','Microsoft'],['GOOGL','Alphabet'],['AMZN','Amazon'],['META','Meta Platforms'],['TSLA','Tesla'],['COST','Costco'],['JPM','JPMorgan Chase (equity model required)']];
let activeCase=null;let pathEditNotice='';let researchCases=[];let companies=[{ticker:'LESSON',name:'Teaching example · synthetic',snapshots:[lesson]}],selected=lesson,a={...defaults},locked=null;
let saved=[];try{const rawSaved=JSON.parse(localStorage.getItem('valuation-lab-cases')||'[]');saved=Array.isArray(rawSaved)?rawSaved.filter(s=>s&&typeof s==='object'&&s.snapshot&&typeof s.snapshot==='object'&&s.assumptions&&typeof s.assumptions==='object'):[]}catch{}
const toast=t=>{$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)};
const download=(name,data)=>{const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=u;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
const fields=[['growth','Near-term revenue growth','Fades to stable growth; no capital release','%',100,-50,100,.5],['targetMargin','Mature operating margin','Linear transition from reported EBIT','%',100,0,100,.5],['salesCapital','Sales / invested capital','Incremental revenue per $ invested','×',1,.1,50,.1],['tax','Cash tax rate','Positive EBIT only; no NOL carryforward','%',100,0,60,.5],['wacc','Cost of capital','Nominal, same currency as cash flow','%',100,.1,100,.25],['terminalGrowth','Stable growth','Below WACC and currency growth ceiling','%',100,0,5,.25],['terminalROIC','Terminal marginal ROIC','Explain any perpetual excess return','%',100,.1,100,.5],['otherAssets','Other nonoperating assets','Excluded from operating cash flows','m',1,0,1e9,1],['otherClaims','Other claims on value','Options, minority interests, obligations','m',1,0,1e9,1]];
function setupFields(){const fieldHTML=fields.map(([k,l,h,u,f,min,max,step])=>`<div class="field-row"><label for="a-${k}">${l}<small id="hint-${k}">${h}</small></label><div class="number-wrap"><input id="a-${k}" data-key="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${Math.round(a[k]*f*1e6)/1e6}" aria-describedby="hint-${k}"><span>${u}</span></div></div>`);$('#assumptions').innerHTML=[['Operating performance',0,4],['Risk & long-term value',4,7],['Equity bridge adjustments',7,9]].map(([title,start,end])=>`<fieldset><legend>${title}</legend>${fieldHTML.slice(start,end).join('')}</fieldset>`).join('');$('#assumptions').oninput=e=>{const f=fields.find(f=>f[0]===e.target.dataset.key);if(f){activeCase=null;if(a.yearlyOverrides&&!['otherAssets','otherClaims'].includes(f[0])){delete a.yearlyOverrides;pathEditNotice='Manual operating-input edit replaced the dated annual path with the simple fade model. Reload the dated research case to restore its frozen growth, margin, tax, investment and discount-rate path.';toast('Simple fade mode active; see the persistent model notice.')}else if(a.yearlyOverrides){pathEditNotice='Bridge edited; the dated annual operating path is retained. Reload the dated case to restore all frozen inputs.'}a[f[0]]=e.target.value===''?NaN:Number(e.target.value)/f[4];render()}};$('#assumptions').onsubmit=e=>e.preventDefault()}
function chooseCompany(ticker){activeCase=null;pathEditNotice='';a={...defaults};setupFields();$('#case-analysis').classList.add('hidden');clearCaseDiagnostics();const c=companies.find(c=>c.ticker===ticker);$('#snapshot').innerHTML=(c?.snapshots||[]).map((s,i)=>`<option value="${i}">FY ending ${esc(s.periodEnd)} · available ${esc(s.availableFrom)}</option>`).join('')||'<option>No verified snapshot loaded</option>';selected=c?.snapshots?.[0]||null;if(selected)$('#asof').value=selected.availableFrom.includes('T')?selected.availableFrom.slice(0,16):selected.availableFrom+'T00:00';render();}
function renderPicker(){const all=[...companies,...popular.filter(([t])=>!companies.some(c=>c.ticker===t)).map(([ticker,name])=>({ticker,name,snapshots:[]}))];$('#company').innerHTML=all.map(c=>`<option value="${esc(c.ticker)}">${esc(c.ticker)} · ${esc(c.name)}${c.snapshots.length?'':' · import needed'}</option>`).join('');$('#company').value=selected?.ticker||'LESSON'}
function chart(v){
 const width=660,height=250,left=65,right=12,top=24,bottom=31,vals=v.rows.flatMap(r=>[r.nopat,r.fcff]),min=Math.min(0,...vals),max=Math.max(...vals,1),y=x=>height-bottom-(x-min)/(max-min)*(height-top-bottom),bar=(width-left-right)/10;
 const ticks=[min,(min+max)/2,max];
 return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">Ten-year cash-flow projection</title><desc id="chart-desc">Operating earnings and free cash flow in ${esc(selected.currency)} millions. Free cash flow is the second bar with a striped fill. Full values are in the annual forecast table.</desc><defs><pattern id="fcff-pattern" width="5" height="5" patternUnits="userSpaceOnUse"><rect width="5" height="5" fill="var(--chart-two)"/><path d="M0 0L5 5" stroke="var(--surface)" stroke-opacity=".22" stroke-width="1"/></pattern></defs><text x="${left}" y="13" fill="var(--muted)" font-size="11">${esc(selected.currency)} millions</text>${ticks.map(t=>`<line x1="${left}" x2="${width-right}" y1="${y(t)}" y2="${y(t)}" stroke="var(--line)"/><text x="${left-9}" y="${y(t)+4}" text-anchor="end" fill="var(--muted)" font-size="11">${n(t,0)}</text>`).join('')}<line x1="${left}" x2="${width-right}" y1="${y(0)}" y2="${y(0)}" stroke="var(--control)"/>${v.rows.map((r,i)=>`<rect x="${left+i*bar+8}" y="${Math.min(y(r.nopat),y(0))}" width="15" height="${Math.max(1,Math.abs(y(0)-y(r.nopat)))}" rx="2" fill="var(--chart-one)"><title>Year ${r.year} NOPAT ${n(r.nopat)} million</title></rect><rect x="${left+i*bar+26}" y="${Math.min(y(r.fcff),y(0))}" width="15" height="${Math.max(1,Math.abs(y(0)-y(r.fcff)))}" rx="2" fill="url(#fcff-pattern)"><title>Year ${r.year} FCFF ${n(r.fcff)} million</title></rect><text x="${left+i*bar+24}" y="${height-8}" fill="var(--muted)" text-anchor="middle" font-size="11">Y${r.year}</text>`).join('')}</svg>`
}
function table(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function render(){
 $('#snapshot-context').textContent=selected?`${selected.ticker} · Period ${selected.periodEnd} · ${selected.currency} millions · Dated, non-live inputs`:'No verified snapshot selected';
 const critical=!selected?($('#company').value==='JPM'?'Financial institution: use an equity/regulatory-capital model. This industrial FCFF model is unsuitable.':'No verified fundamentals loaded. Import a sourced snapshot in Data & sources to begin.'):selected?.snapshotMode==='annual-reference'?(selected.bridgeReviewed?'Annual reference only. Provisional claim inputs reviewed; verify accounting judgments before relying on the result.':'Annual reference only. Review the filing details and equity claims below before this provisional valuation is enabled.'):selected?.ticker==='LESSON'?'Synthetic teaching example. These are invented numbers, not a real company.':'';
 $('#critical-notice').textContent=critical;$('#critical-notice').classList.toggle('hidden',!critical);

 $('#model-mode').textContent=pathEditNotice||(a.yearlyOverrides?'Dated annual path active. Editing an operating assumption switches the entire path to the simple fade model. Editing other assets or claims preserves the path.':'Simple fade model active.');
 if(!selected){$('#snapshot-notice').textContent=$('#company').value==='JPM'?'Financial institution: use an equity/regulatory-capital model. This industrial FCFF model is unsuitable.':'No verified fundamentals loaded for this company. Import a sourced snapshot in Data & methodology to begin.';$('#selected-evidence').innerHTML='';$('#valuation-result').innerHTML='<div class="error">Valuation unavailable until a valid snapshot is loaded.</div>';for(const id of ['chart','scenarios','sensitivity','bridge','forecast'])$('#'+id).innerHTML='';return}
 $('#case-notice').classList.add('hidden');$('#snapshot-notice').innerHTML=`${selected.ticker==='LESSON'?'<b>Synthetic teaching example.</b> ':''}${selected.snapshotMode==='annual-reference'?'<b>Dated annual reference, not live or latest-quarter data.</b> ':''}${esc(selected.currency)} millions · shares in millions · period ${esc(selected.periodEnd)} · available ${esc(selected.availableFrom)} · ${esc(selected.shareBasis||'share basis not specified')}. <a target="_blank" rel="noopener" href="${esc(selected.sourceUrl)}">Source ↗</a>${selected.caseAdjustmentNotes?' <b>Model adjustments:</b> '+esc(selected.caseAdjustmentNotes):''}${selected.notes?' '+esc(typeof selected.notes==='string'?selected.notes:JSON.stringify(selected.notes)):''}`;
 $('#bridge-review-label').classList.toggle('hidden',selected.snapshotMode!=='annual-reference');$('#bridge-reviewed').checked=!!selected.bridgeReviewed;const raw=selected.raw||{},facts=raw.facts||{},guidance=raw.guidance;
 $('#selected-evidence').innerHTML=(selected.caseAdjustmentNotes?'<p><b>Model-input amounts below include disclosed case adjustments. The source ledger retains original filing facts.</b></p>':'')+table(['Reported revenue','Reported EBIT','Cash / securities','Debt','Outstanding shares'],[[n(selected.revenue,0)+'m',n(selected.ebit,0)+'m',n(selected.cash,0)+'m',n(selected.debt,0)+'m',n(selected.shares,2)+'m']])+`<p class="micro">${esc(raw.cashDefinition||'Check whether cash is nonoperating and unrestricted.')} ${esc(raw.debtDefinition||'Check leases, options and other claims separately.')} ${esc(raw.sharesNote||'Confirm the dated share count and dilution treatment.')} Share date: ${esc(selected.coverShareDate||'not specified')}. ${esc(raw.vintage||'User-supplied or illustrative data: verify original filing vintage.')}</p>`+(guidance?`<p><b>Contemporaneous guidance, ${esc(guidance.publishedDate)}:</b> ${esc(guidance.period)} revenue midpoint ${n(guidance.revenueMidpointUSDmillions,0)}m. This is quarterly management guidance, not annual actuals or a long-term forecast. <a href="${esc(guidance.sourceUrl)}" target="_blank" rel="noopener">Read the release ↗</a></p>`:'')+(facts.gamingRevenue?`<p class="micro">Market-platform revenues: Gaming ${n(facts.gamingRevenue,0)}m · Data Center ${n(facts.dataCenterRevenue,0)}m. These are not necessarily reportable operating segments.</p>`:'');
 let v;try{v=valueCompany(selected,a)}catch(e){$('#valuation-result').innerHTML=`<div class="error">${esc(e.message)}</div>`;for(const id of ['chart','scenarios','sensitivity','bridge','forecast'])$('#'+id).innerHTML='';return}
 $('#valuation-result').innerHTML=`<div class="hero-result"><p class="eyebrow">CONDITIONAL INTRINSIC VALUE · ${esc(selected.currency)} / SHARE</p><div class="value">${n(v.perShare,2)}<small>per share</small></div><div class="hero-meta"><div>Operating enterprise value<b>${n(v.enterprise,0)}m</b></div><div>Terminal value contribution<b>${pct(v.terminalShare)}</b></div><div>Market comparison<b>Price not loaded</b></div></div></div>${v.equity<0?'<div class="error">Common equity residual is negative. Display floored at zero; this simple DCF does not model distressed debt or equity option value.</div>':''}${a.terminalROIC>a.wacc+.005?'<p class="micro">Your terminal ROIC exceeds WACC. The story needs a durable competitive advantage extending into perpetuity.</p>':''}`;
 $('#chart').innerHTML=chart(v);
 $('#scenarios').innerHTML=[['Bear',-.03,-.03,.01],['Base',0,0,0],['Bull',.03,.03,-.01]].map(([label,g,m,w])=>{let x={...a,yearlyOverrides:undefined,growth:Math.max(-.5,a.growth+g),targetMargin:Math.max(0,Math.min(1,a.targetMargin+m)),wacc:a.wacc+w};if(activeCase?.scenarios?.[label.toLowerCase()])x={...defaults,...activeCase.scenarios[label.toLowerCase()]};if(label==='Base')x=a;let val;try{val=n(valueCompany(selected,x).perShare,2)}catch{val='Invalid'}let year10;try{year10=valueCompany(selected,x).rows.at(-1).revenue}catch{}return `<article><p>${label.toUpperCase()} CASE</p><h3>${val}</h3><small>${pct(x.growth)} growth<br>${pct(x.targetMargin)} margin${activeCase?'<br>Year 10 revenue '+n(year10,0)+'m':''}</small></article>`}).join('');
 $('#scenario-label').textContent=activeCase?.scenarios?'Dated correlated scenarios':'Illustrative stress cases';$('#scenario-note').textContent=activeCase?.scenarios?'Uncalibrated bear/base/bull economic states; not probabilities or confidence intervals. Long-run revenue and margins remain analyst assumptions; inspect the dated evidence and scale constraints.':'Bear/bull change growth ±3pp, terminal margin ±3pp and WACC ±1pp using a simple fade. These are stress tests, not probabilities.';const gs=[Math.max(0,a.terminalGrowth-.01),a.terminalGrowth,Math.min(.05,a.terminalGrowth+.01)];$('#sensitivity').innerHTML=table(['WACC / g',...gs.map(pct)],[-.01,0,.01].map(d=>[pct(a.wacc+d),...gs.map(g=>{try{return n(valueCompany(selected,{...a,wacc:a.wacc+d,terminalGrowth:g,...(a.yearlyOverrides?{yearlyOverrides:a.yearlyOverrides.map(o=>({...o,wacc:o.wacc+d}))}:{})}).perShare,2)}catch{return '—'}})]));
 $('#bridge').innerHTML=[['Operating enterprise value',v.enterprise],['+ Cash',selected.cash],['+ Other nonoperating assets',a.otherAssets],['− Debt',-selected.debt],['− Other claims',-a.otherClaims],['Common equity residual',v.equity]].map(([k,x],i)=>`<div class="bridge-row ${i===5?'total':''}"><span>${k}</span><b>${n(x,0)}m</b></div>`).join('');
 $('#forecast').innerHTML=table(['Year','Revenue','Growth','Margin','NOPAT','Reinvestment','FCFF','WACC','PV of FCFF'],v.rows.map(r=>[r.year,n(r.revenue),pct(r.growth),pct(r.margin),n(r.nopat),n(r.reinvestment),n(r.fcff),pct(r.wacc),n(r.pv)]));
}
function persist(){try{localStorage.setItem('valuation-lab-cases',JSON.stringify(saved))}catch{toast('Browser storage unavailable. Export a JSON copy.')}renderExperiments()}
function renderExperiments(){$('#experiments').innerHTML=saved.length?saved.map((s,i)=>`<article><b>${esc(s.snapshot.ticker)} · ${esc(s.asOf)} · v${s.version||1}</b> · intrinsic value ${n(s.intrinsicValue,2)} ${esc(s.snapshot.currency)} / historical share<br><small>Locked ${esc(s.createdAt)} · ${s.hindsightInformed?'hindsight-informed revision':'retrospective'} · ${esc(s.thesis||'No thesis recorded')}${s.diagnosis?' · Diagnosis: '+esc(s.diagnosis.type)+' — '+esc(s.diagnosis.note):''}</small><br><button class="quiet" data-download="${i}">Export locked case ↓</button></article>`).join(''):'<p class="muted">No locked experiments yet. Your cases will appear here.</p>';document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download('locked-case.json',saved[Number(b.dataset.download)]))}
function asofCheck(){const c=companies.find(c=>c.ticker===$('#company').value),ss=eligibleSnapshots(c?.snapshots||[],$('#asof').value+'Z');$('#eligibility').innerHTML=ss.length?`<b class="good">${ss.length} eligible filing(s).</b><br>Latest period: ${esc(ss[0].periodEnd)}. Current selection ${selected&&ss.some(s=>s.periodEnd===selected.periodEnd&&s.sourceUrl===selected.sourceUrl)?'is eligible.':'is not eligible; choose an eligible snapshot in the workbench.'}`:'<span class="error">No filing available on this date.</span>';return ss}
function renderLedger(){const rows=companies.flatMap(c=>c.snapshots.map(s=>[esc(c.ticker),esc(s.periodEnd),esc(s.filedAt),esc(s.availableFrom),esc(s.shareBasis),`<a rel="noopener" target="_blank" href="${esc(s.sourceUrl)}">Original source ↗</a>`]));$('#ledger').innerHTML=table(['Company','Fiscal period end','Filed','Available from','Share convention','Evidence'],rows);const nv=companies.find(c=>c.ticker==='NVDA');$('#nvda-ledger').innerHTML=nv?table(['Fiscal period end','Available from','Shares (m)','Share convention'],nv.snapshots.map(s=>[esc(s.periodEnd),esc(s.availableFrom),n(s.shares,2),esc(s.shareBasis)])):'<p class="muted">NVIDIA annual source snapshots are not loaded yet. Import verified original filings to run these cases.</p>'}
const questions=[{q:'A business has next-year NOPAT of 100, a 10% cost of capital and a 10% marginal ROIC. What happens to value when stable growth rises from 2% to 4%, holding next-year NOPAT fixed?',options:['Value rises because earnings grow faster.','Value remains 1,000.','Value falls because reinvestment rises.'],answer:1,why:'At ROIC = WACC, growth is value neutral with forward NOPAT held fixed. V = NOPAT × (1 − g/ROIC) / (WACC − g) = NOPAT/WACC. Higher growth consumes exactly the value of additional future earnings.'},{q:'Revenue increases by 200 and incremental sales-to-capital is 2. After-tax operating income is 120. What is FCFF?',options:['120','100','20'],answer:2,why:'Reinvestment = 200/2 = 100. FCFF = 120 − 100 = 20. Revenue growth must be funded, even when the reported operating margin looks attractive.'},{q:'You are valuing a bank. Is subtracting deposits from an industrial FCFF enterprise value a reliable default?',options:['Yes, deposits are debt.','No. Funding is operational; use an equity and regulatory-capital model.','Yes, as long as WACC is low.'],answer:1,why:'Debt-like funding is part of a bank’s operations. Required capital, credit losses and distributable equity cash flows need explicit modeling. The industrial enterprise-to-equity bridge is generally unsuitable.'},{q:'A fiscal year ends January 31. Its annual report is filed March 15. Can those numbers be used for a February 1 historical valuation?',options:['Yes, because the fiscal period is complete.','No, unless they were already publicly disclosed in another verified source.','Yes, if the final numbers were accurate.'],answer:1,why:'Availability, not fiscal period end, determines the information set. A later restatement also cannot silently replace an original filing vintage.'},{q:'Consolidated FCFF includes 100% of a subsidiary. The parent owns 80%. What belongs in the equity bridge?',options:['Add the 20% noncontrolling interest.','Subtract the value of the 20% noncontrolling claim once.','No adjustment is ever needed.'],answer:1,why:'The operating value includes all consolidated cash flows. The noncontrolling owners’ economic claim must be removed to get common equity attributable to the parent.'},{q:'A stock outperforms for one year after a low DCF valuation. What does that establish?',options:['The DCF formula is wrong.','The strategy has predictive alpha.','Neither model validity nor strategy alpha follows from one price path.'],answer:2,why:'Prices respond to new information and changing discount rates. Assess forecast calibration, valuation assumptions and market returns separately. Robust strategy claims require point-in-time data, a predeclared universe and out-of-sample evaluation.'}];
function quizzes(){$('#quizzes').innerHTML=questions.map((q,i)=>`<article class="panel quiz"><p class="eyebrow">QUESTION ${String(i+1).padStart(2,'0')}</p><h2>${q.q}</h2><div class="quiz-options">${q.options.map((o,j)=>`<button data-q="${i}" data-a="${j}">${String.fromCharCode(65+j)}. ${o}</button>`).join('')}</div><div class="quiz-feedback" id="feedback-${i}" aria-live="polite"></div></article>`).join('');document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const i=+b.dataset.q,j=+b.dataset.a,q=questions[i];document.querySelectorAll(`[data-q="${i}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#feedback-'+i).innerHTML=`<b>${j===q.answer?'Correct.':'Revisit the mechanism.'}</b> ${q.why}`});const pass=Math.abs(terminalValue(100,.1,.04,.1)-1000)<1e-8&&terminalValue(100,.1,.04,.05)<terminalValue(100,.1,.02,.05);$('#checks').textContent=pass?'✓ Terminal growth neutrality and below-hurdle growth checks pass in this browser.':'Model check failure. Do not use outputs.'}
function parseImport(text){if(text.trim().startsWith('{'))return JSON.parse(text);const lines=text.trim().split(/\r?\n/);if(lines.length!==2)throw new Error('CSV needs one header and one data row. Use JSON for complex fields.');const keys=lines[0].split(',').map(s=>s.trim()),vals=lines[1].split(',').map(s=>s.trim());if(keys.length!==vals.length)throw new Error('CSV columns mismatch; quoted commas not supported. Use JSON.');const obj=Object.fromEntries(keys.map((k,i)=>[k,['revenue','ebit','cash','debt','shares'].includes(k)?Number(vals[i]):vals[i]]));return obj}
$('#company').onchange=e=>chooseCompany(e.target.value);$('#snapshot').onchange=e=>{selected=companies.find(c=>c.ticker===$('#company').value)?.snapshots[+e.target.value]||null;activeCase=null;pathEditNotice='';a={...defaults};setupFields();$('#case-analysis').classList.add('hidden');clearCaseDiagnostics();if(selected)$('#asof').value=selected.availableFrom.includes('T')?selected.availableFrom.slice(0,16):selected.availableFrom+'T00:00';render()};$('#reset').onclick=()=>{activeCase=null;pathEditNotice='';a={...defaults};setupFields();render()};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.page').forEach(p=>p.classList.toggle('hidden',p.id!==b.dataset.tab));document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-current',x===b?'page':'false')});$('#breadcrumb').textContent='Workspace / '+b.textContent.trim();history.replaceState(null,'','#'+b.dataset.tab);window.scrollTo(0,0)});
$('#save').onclick=()=>{try{if(!selected)throw new Error('Load a valid snapshot first');const asOf=selected.availableFrom;const l=lockExperiment(selected,a,asOf);l.thesis=$('#thesis').value;saved.push(l);persist();toast('Research case saved in this browser.')}catch(e){toast(e.message)}};
$('#export').onclick=()=>{try{const v=valueCompany(selected,a);download('valuation-case.json',{schemaVersion:1,snapshot:selected,assumptions:a,thesis:$('#thesis').value,result:v,exportedAt:new Date().toISOString()})}catch(e){toast(e.message)}};
$('#check-asof').onclick=asofCheck;
$('#lock').onclick=()=>{try{if(!selected)throw new Error('Select a valid company snapshot first');if(!$('#thesis').value.trim())throw new Error('Write the business story in the workbench before locking');locked=lockExperiment(selected,a,$('#asof').value+'Z');locked.thesis=$('#thesis').value;if(activeCase)locked.provenance={originalFreezeSHA256:activeCase.originalFreezeSHA256,classification:activeCase.classification,sourceUrls:activeCase.sourceUrls,sourceAssumptionLedger:activeCase.sourceAssumptionLedger,accounting:activeCase.accounting,snapshotOverrides:activeCase.snapshotOverrides||activeCase.snapshotOverride,snapshotAdjustmentNotes:activeCase.snapshotAdjustmentNotes};locked.version=1;locked.forecast=valueCompany(selected,a).rows;saved.push(locked);persist();$('#lock-status').textContent=`Locked ${selected.ticker} for ${locked.asOf}. Subsequent edits will not change this record.`;for(const id of ['history-results','actual-results','original-scorecard-results','reverse-results'])$('#'+id).innerHTML='';toast('Assumptions frozen. You can now reveal outcomes.')}catch(e){$('#lock-status').textContent=e.message}};
$('#evaluate').onclick=()=>{try{const r=evaluateHistory(locked,JSON.parse($('#prices').value));$('#history-results').innerHTML=`<b>Entry observation: ${esc(r.entry.date)} · ${n(r.entry.close,2)}</b>${table(['Date','Price','Price return'],r.observations.map(p=>[esc(p.date),n(p.close,2),pct(p.priceReturn)]))}<p class="micro">${esc(r.warning)}</p>`}catch(e){$('#history-results').textContent=e.message}};
$('#file').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>2e6){toast('Use a file smaller than 2 MB.');return}$('#import-text').value=await f.text()}};
$('#import').onclick=()=>{try{const imported=parseImport($('#import-text').value),s=imported.snapshot||imported,errors=validateSnapshot(s);if(errors.length)throw new Error(errors.join('; '));if(imported.assumptions)valueCompany(s,imported.assumptions);let c=companies.find(c=>c.ticker===s.ticker);if(!c){c={ticker:s.ticker,name:s.name||s.ticker,snapshots:[]};companies.push(c)}c.snapshots.unshift(s);selected=s;if(imported.assumptions){a={...defaults,...imported.assumptions};setupFields();$('#thesis').value=imported.thesis||''}renderPicker();chooseCompany(s.ticker);if(imported.assumptions){a={...defaults,...imported.assumptions};setupFields();render()}renderLedger();$('#import-result').textContent='Valid snapshot loaded. Open Valuation workbench to use it.';toast('Snapshot imported locally.')}catch(e){$('#import-result').textContent=e.message}};
$('#template').onclick=()=>download('snapshot-template.json',{...lesson,ticker:'REPLACE',name:'Your company',shareBasis:'period-end outstanding, specify split basis',notes:'Replace every teaching number with sourced inputs.'});
setupFields();renderPicker();chooseCompany('LESSON');renderLedger();renderExperiments();quizzes();
try{const response=await fetch('./data/companies.json');if(response.ok){const data=await response.json();for(const c of data.companies||[]){const normalized=normalizeCompany(c);companies.push(normalized)}renderPicker();renderLedger();if(companies.some(c=>c.ticker==='NVDA')){$('#company').value='NVDA';chooseCompany('NVDA')}}}catch(e){console.warn('Verified dataset unavailable',e)}
if(location.hash){document.querySelector(`[data-tab="${CSS.escape(location.hash.slice(1))}"]`)?.click()}

$('#reveal-actuals').onclick=async()=>{try{if(!locked)throw new Error('Lock an experiment before revealing later filings');if(locked.snapshot.raw?.id==='MSFT-FY2019'){$('#original-scorecard').click();$('#actual-results').innerHTML='The sourced Microsoft FY2020–FY2021 comparison appears in the original scorecard below. No later annual-reference snapshot is used as a matched next-year outcome.';return}const c=companies.find(c=>c.ticker===locked.snapshot.ticker);let outcome=[];if(locked.snapshot.ticker==='NVDA'){try{const o=await(await fetch('./data/nvda-fy2025-outcome.json')).json();outcome=[{periodEnd:o.periodEnd,revenue:o.facts.revenue,ebit:o.facts.EBIT,sourceUrl:o.sourceURL}]}catch{}}const later=[...(c?.snapshots||[]),...outcome].filter(s=>s.periodEnd>locked.snapshot.periodEnd).sort((x,y)=>x.periodEnd.localeCompare(y.periodEnd));if(!later.length)throw new Error('No subsequent sourced operating snapshot loaded for this case');const forecast=valueCompany(locked.snapshot,locked.assumptions).rows;$('#actual-results').innerHTML=table(['Fiscal period','Forecast revenue','Actual revenue','Revenue error','Forecast margin','Actual margin','Forecast FCFF'],later.map(s=>{const offset=Math.round((Date.parse(s.periodEnd)-Date.parse(locked.snapshot.periodEnd))/(365.25*864e5));const r=forecast[offset-1];return [`<a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener">${esc(s.periodEnd)} ↗</a>`,r?n(r.revenue,0):'—',n(s.revenue,0),r?pct((r.revenue-s.revenue)/s.revenue):'—',r?pct(r.margin):'—',pct(s.ebit/s.revenue),r?n(r.fcff,0):'—']}))+'<p class="micro">Revenue error = (forecast − actual) / actual. Fiscal periods matched by nearest annual interval. Reported CFO − capex is not unlevered FCFF: actual FCFF error remains unavailable until interest, taxes, working capital and accounting adjustments are reconciled. Later source filings are available in the ledger.</p>'}catch(e){$('#actual-results').textContent=e.message}};
$('#revise').onclick=()=>{try{if(!locked)throw new Error('Lock an experiment first');if(selected?.ticker!==locked.snapshot.ticker)throw new Error('Select the locked company before revising its case');if(!$('#diagnosis').value.trim())throw new Error('Add evidence and a next test before saving a revision');const revised=lockExperiment(locked.snapshot,a,locked.asOf);revised.parentId=locked.id;if(locked.provenance)revised.provenance=locked.provenance;revised.version=(locked.version||1)+1;revised.hindsightInformed=true;revised.thesis=$('#thesis').value;revised.diagnosis={type:$('#diagnosis-type').value,note:$('#diagnosis').value};revised.forecast=valueCompany(locked.snapshot,a).rows;saved.push(revised);locked=revised;persist();toast('New version saved. Original assumptions preserved.')}catch(e){toast(e.message)}};

try{const response=await fetch('./data/nvda-researched-cases.json');if(response.ok){const data=await response.json();researchCases=Array.isArray(data)?data:(data.cases||[]);}else researchCases=(await(await fetch('./data/nvda-cases.json')).json()).cases||[]}catch{}
$('#load-case').onclick=()=>{clearCaseDiagnostics();pathEditNotice='';const c=researchCases.find(c=>c.snapshotId===selected?.raw?.id);if(!c){toast('No dated case available for this snapshot. Write your own sourced assumptions.');return}activeCase=c;if(c.snapshotOverrides||c.snapshotOverride){const original=companies.find(company=>company.ticker===selected.ticker)?.snapshots.find(s=>s.raw?.id===c.snapshotId)||selected;const overrides=Object.fromEntries(Object.entries(c.snapshotOverrides||c.snapshotOverride).filter(([k])=>['shares','debt','ebit','cash','revenue'].includes(k)));selected={...original,...overrides,shareBasis:c.adjustedShareBasis||c.snapshotOverride?.shareBasis||original.shareBasis,coverShareDate:c.snapshotOverride?.coverShareDate||original.coverShareDate,caseAdjustmentNotes:c.snapshotAdjustmentNotes||'Case-specific model adjustments; inspect the source-to-model bridge.'}}a={...defaults,...c.assumptions};$('#thesis').value=c.thesis;$('#case-notice').classList.remove('hidden');$('#case-notice').innerHTML=`<b>${esc(c.classification)}</b><br>${esc(c.thesis)}<br>${esc((c.uncertainty||[]).join(' '))}<br>${(c.sourceUrls||[]).map((u,i)=>`<a href="${esc(u)}" target="_blank" rel="noopener">Evidence ${i+1} ↗</a>`).join(' · ')}`;setupFields();render();$('#case-notice').classList.remove('hidden');$('#case-analysis').classList.remove('hidden');$('#case-analysis-content').innerHTML=(c.snapshotId==='NVDA-FY2021'?'<div class="notice"><b>Versioned arithmetic correction:</b> the source ledger’s platform-growth bridge sums to 32.0186%, not 32.5%. The original frozen 32.5% forecast and $247.06 value are preserved. A separately computed arithmetic-consistent diagnostic yields $246.22; it is a post-freeze correction, not improved historical foresight.<br><b>Separate mechanism stresses:</b> a genuine contracting-cycle bear case is $92.29 versus the original $102.75 bear. Fading sales-to-capital to 0.6751 by year ten (consistent with 16% mature ROIC at a 30% margin and 21% tax) gives $243.62 versus $247.06. The original path implies a 71.1% incremental return before an abrupt 16% terminal regime; the original freeze stays unchanged.<br><b>Unresolved awards:</b> a 0–5% equity haircut is only a sensitivity, not a valuation of outstanding options or RSUs.</div>':'')+table(['Dated evidence','Source location','Forecast interpretation'],(c.sourceAssumptionLedger||[]).map(r=>[esc(r.fact),esc(r.source),esc(r.inference)]))+'<h3>Accounting treatment & unresolved claims</h3>'+Object.entries(c.accounting||{}).map(([k,v])=>'<p><b>'+esc(k)+':</b> '+esc(v)+'</p>').join('')+'<h3>Missing mechanisms / diagnostics</h3><p>'+esc((c.diagnosticFlags||[]).join(' '))+'</p><p class="micro">Freeze: '+esc(c.freezeTimestampUTC)+' · SHA256 '+esc(c.originalFreezeSHA256)+'</p>';toast('Dated assumptions loaded; review the evidence and limitations before locking.')};
$('#sparse-prices').onclick=async()=>{try{if(!locked||locked.snapshot.ticker!=='NVDA')throw new Error('Lock an NVIDIA case first');const d=await(await fetch('./data/nvda-price-observations.json')).json();const start=d.observations.find(o=>o.date>locked.asOf.slice(0,10)||(o.date===locked.asOf.slice(0,10)&&locked.asOf.slice(11,16)<='14:30')),end=d.observations.find(o=>o.date===d.endpointDate);if(!start||!end||start.date===end.date)throw new Error('No later price pair for this cutoff');const divisor=locked.snapshot.raw?.fiscalYear===2021?40:10;$('#history-results').innerHTML=`<b>Sparse historical observations, not a strategy backtest</b>${table(['Observation','Split-adjusted price','Evidence'],[start,end].map(o=>[esc(o.date),n(o.splitAdjustedPrice,3),`<a href="${esc(o.sourceUrl)}" target="_blank" rel="noopener">${esc(o.sourceTitle)} ↗</a>`]))}<p>Price-only return: ${pct(end.splitAdjustedPrice/start.splitAdjustedPrice-1)}. Locked intrinsic value on the same post-June-2024 split basis: ${n(locked.intrinsicValue/divisor,2)} USD/share.</p><p class="micro">Entry observation is the first sourced date on or after the cutoff (${esc(start.date)}), not necessarily that day's open or official close. ${esc(start.reportedPriceType)}. ${esc(d.dividends)} Four ex-post selected dates, unequal holding periods, one common endpoint. Future splits are used only for outcome unit reconciliation. No daily series or licensed market feed.</p>`}catch(e){$('#history-results').textContent=e.message}};

$('#bridge-reviewed').onchange=e=>{if(selected){selected.bridgeReviewed=e.target.checked;render()}};

$('#snapshot-export').onclick=()=>{if(selected)download(selected.ticker+'-snapshot.json',selected);else toast('Choose a loaded snapshot first')};

$('#reverse-dcf').onclick=async()=>{try{if(!locked)throw new Error('Lock a case before revealing reverse-DCF diagnostics');const d=await(await fetch('./data/reverse-dcf-diagnostics.json')).json();const c=d.cases.find(c=>c.snapshotId===locked.snapshot.raw?.id);if(!c)throw new Error('No independently tested reverse diagnostic for this snapshot');$('#reverse-results').innerHTML=table(['Original frozen base','Original bull','Dated quote','Bull / quote gap'],[[n(c.baseValue,2),n(c.bullValue,2),n(c.quoteOriginalBasis,2),n(c.bullToQuoteGapPct,1)+'%']])+`<p class="micro">These diagnostics refer to the original researched freeze, not your edited local case. <a href="${esc(c.quoteSource)}" target="_blank" rel="noopener">Quote evidence ↗</a> · ${esc(c.quoteDate)}. ${esc(c.timing)} ${esc(c.quoteCharacterization)}</p><p><b>Conditional operating path:</b> add ${n(c.growthPremiumDiagnostic.parameter*100,2)} percentage points to each of the first five growth rates, taper to zero by year ten, retaining all other assumptions. Implied year-one growth ${pct(c.growthPremiumDiagnostic.year1Growth)}; year-five revenue ${n(c.growthPremiumDiagnostic.year5Revenue,0)}m.</p><p><b>Alternative conditional discount rate:</b> shift all annual and terminal WACC rates by ${n(c.waccShiftDiagnostic.parameter*100,2)} percentage points; implied terminal WACC ${pct(c.waccShiftDiagnostic.impliedTerminalWacc)}. This is not an observed historical rate.</p><p class="micro">${esc(c.interpretation)} These are value-to-price gaps, not errors against a known true intrinsic value. Nothing is applied to the original forecast.</p>`}catch(e){$('#reverse-results').textContent=e.message}};

$('#original-scorecard').onclick=async()=>{try{if(!locked)throw new Error('Lock a case before revealing its original scorecard');if(locked.snapshot.raw?.id==='MSFT-FY2019'){const d=await(await fetch('./data/msft-business-outcome-evaluation.json')).json();$('#original-scorecard-results').innerHTML='<h3>Microsoft: original frozen business forecast</h3>'+table(['Outcome year','Base revenue forecast','Actual revenue','Revenue error','EBIT error','Margin error (pp)'],d.evaluations.map(e=>{const c=e.comparison.base;return [`<a href="${esc(e.sourceURL)}" target="_blank" rel="noopener">FY${e.fiscalYear} ↗</a>`,n(c.forecastRevenue,0),n(c.actualRevenue,0),n(c.revenueErrorPct,2)+'%',n(c.ebitErrorPct,2)+'%',n(c.marginErrorPercentagePoints,2)]}))+`<p>${esc(d.interpretation)}</p><p class="micro">Errors = (forecast − actual) / actual. Original frozen assumptions only; your local edits are not scored here. No actual unlevered FCFF, market-price or return evaluation is claimed. <a href="./data/msft-business-outcome-evaluation.json" target="_blank">Full three-state outcome evaluation</a> · <a href="./data/msft-independent-check.json" target="_blank">Independent arithmetic checks and sensitivities</a> · <a href="./data/msft-annual-scenario-paths.csv" download>Annual scenario paths CSV</a></p>`;return}const d=await(await fetch('./data/frozen-case-evaluation.json')).json();const c=d.cases.find(c=>c.snapshotId===locked.snapshot.raw?.id);if(!c)throw new Error('No original scorecard for this snapshot');$('#original-scorecard-results').innerHTML='<h3>Operating forecasts: original frozen research case</h3>'+table(['Outcome fiscal year','Forecast revenue','Actual revenue','Revenue error','Margin error (pp)','EBIT error'],c.businessForecastComparisons.map(r=>[`<a href="${esc(r.actualSource)}" target="_blank" rel="noopener">FY${r.actualFiscalYear} ↗</a>`,n(r.forecastRevenue,0),n(r.actualRevenue,0),n(r.revenueErrorPct,1)+'%',n(r.operatingMarginErrorPercentagePoints,1),n(r.ebitErrorPct,1)+'%']))+`<p class="micro">${esc(c.businessOutcomeStatus)}. Revenue/EBIT error = (forecast − actual) / actual. Actual unlevered FCFF remains unconstructed. These numbers refer to the original frozen case, not your edited assumptions.</p><h3>Market comparison: a different question</h3><p>Base value-to-price gap: ${n(c.baseValueToPriceGapPct,1)}%. Subsequent price-only return to ${esc(c.returnEndDate)}: ${n(c.subsequentPriceOnlyReturnPct,1)}%.</p><p class="micro">${esc(c.gapMeaning)}. Entry-day quote was observed after the research cutoff. ${esc(c.entryPriceCharacterization)}. ${esc(d.priceReturnLimits)} ${esc(d.caseSelectionLimits)}</p>`}catch(e){$('#original-scorecard-results').textContent=e.message}};

$('#research-addenda').onclick=async()=>{try{if(!activeCase)throw new Error('Load a dated research case first');if(activeCase.snapshotId==='MSFT-FY2019'){ $('#research-addenda-results').innerHTML='<p>Microsoft accounting, rate assumptions and terminal capital fade are documented in the dated case above and its <a href="./data/research-versions/MSFT-FY2019-frozen-v1.json" target="_blank">original versioned freeze</a>. It has no NVIDIA quarterly-guidance addendum.</p>';return}const d=await(await fetch('./data/research-addenda.json')).json(),c=d.cases.find(c=>c.snapshotId===activeCase.snapshotId),b=d.quarterlyBridge.find(c=>c.snapshotId===activeCase.snapshotId);if(!c)throw new Error('No supplemental checks available');const rf=c.rateEvidence.riskFree,erp=c.rateEvidence.equityRiskPremium;$('#research-addenda-results').innerHTML=`<div class="notice"><b>Post-freeze checks, original forecasts unchanged.</b> ${esc(d.classification)}. This is a diagnostic version after additional research, not an improved original track record.</div><p>Annual base forecast requires Q2–Q4 average revenue ${n(b.requiredQ2ThroughQ4AverageRevenue,0)}m, ${pct(b.remainingQuarterAverageVsQ1)} above the guided first quarter. This is an explicit recovery/acceleration requirement, not management’s full-year guidance.</p>${activeCase.snapshotId==='NVDA-FY2022'?'<p class="error">Known risk omitted from the original narrative: sales to Russia had ceased by the filing; February earnings guidance predated the invasion. The original March case was not a comprehensive event-adjusted forecast. No unsupported geographic loss is invented here.</p>':''}${activeCase.snapshotId==='NVDA-FY2021'?'<p class="error">Standalone limitation: the original valuation omits the contingent Arm transaction. Closing cash, new shares, earnouts, incremental Arm value and net synergies require a separate state model. No closing probability is assigned, and the announced deal price is not intrinsic value.</p>':''}${activeCase.snapshotId==='NVDA-FY2024'?'<p class="micro">Concentration denominators matter: the China 14% reference is a share of Data Center revenue; the indirect-customer 19% reference is a share of total revenue.</p>':''}<h3>Historical rate anchors, assumed beta</h3><p><a href="${esc(rf.sourceURL)}" target="_blank" rel="noopener">Prior-session 10-year Treasury</a>: ${n(rf.percentPerYear,2)}% (${esc(rf.observationDate)}). <a href="${esc(erp.sourceURL)}" target="_blank" rel="noopener">Dated January ERP</a>: ${n(erp.percentPerYear,2)}%. Historical Treasury observations are from the current official series, not certified as-released vintages.</p>${table(['Assumed initial beta','Initial discount rate','Terminal discount rate','Conditional value / share'],c.stresses.map(s=>[n(s.assumedInitialOperatingBeta,1),pct(s.initialUnleveredDiscountRate),pct(s.terminalUnleveredDiscountRate),n(s.perShare,2)]))}<p class="micro">${esc(d.method)} ${esc(d.limitations.join(' '))} These hypothetical all-equity operating rates omit debt tax shields and are not a reconstruction of historical levered WACC.</p>`}catch(e){$('#research-addenda-results').textContent=e.message}};

try{const response=await fetch('./data/msft-researched-cases.json');if(response.ok){const d=await response.json();researchCases.push(...(Array.isArray(d)?d:(d.cases||[])))}}catch{}
$('#open-baseline').onclick=()=>{const c=companies.find(c=>c.ticker==='MSFT'),index=c?.snapshots.findIndex(s=>s.raw?.id==='MSFT-FY2019');if(index==null||index<0){toast('The original Microsoft FY2019 snapshot is not yet available.');return}$('#company').value='MSFT';chooseCompany('MSFT');$('#snapshot').value=String(index);$('#snapshot').onchange({target:$('#snapshot')});document.querySelector('[data-tab="workbench"]').click();$('#load-case').click()};

$('#claim-scale').onclick=async()=>{try{if(!activeCase?.snapshotId?.startsWith('NVDA'))throw new Error('Load a dated NVIDIA research case first');const d=await(await fetch('./data/nvda-claim-scale-diagnostics.json')).json(),award=d.awards.cases.find(c=>c.snapshotId===activeCase.snapshotId);let html=`<div class="notice">Post-freeze source checks. Original forecasts and scores remain unchanged.</div><h3>Existing equity awards: evidence, not a completed net claim</h3><p><a href="${esc(award.sourceUrl)}" target="_blank" rel="noopener">Original filing award note ↗</a>: ${n(award.awardUnitsOutstandingMillions,0)}m units outstanding at ${esc(award.sourceDate)}, ${pct(award.grossUnitsAsPctOfCoverShares)} of cover-date shares. Period-end award counts and cover-date common shares are different dated observations.</p><p class="micro">${esc(d.awards.method)} ${esc(d.awards.noDoubleCounting)} ${esc(d.awards.remainingGap)}</p>`;if(activeCase.snapshotId==='NVDA-FY2024'){const z=d.scale;html+=`<h3>Does the implied terminal scale fit a market?</h3><p><a href="${esc(z.source.url)}" target="_blank" rel="noopener">Issuer October 2023 presentation, page 33 ↗</a>: $300bn Data Center Systems and $1tn broader long-term annual opportunity claims. This is promotional, untimed issuer evidence, not a validated customer-spending forecast. Do not confuse installed infrastructure stock with annual spending.</p>${table(['Original state','First terminal-year revenue ($bn)','Implied Data Center share of $300bn TAM'],z.cases.map(c=>[esc(c.state),n(c.firstTerminalYearRevenueUSDmillions/1000,1),pct(c.constantCurrentPlatformMixDiagnostic.shareOfManagement300bnDataCenterSystemsOpportunity)]))}<p class="error">The original bull path implies 152.7% of the issuer’s stated Data Center Systems opportunity if the current platform mix is held constant. It requires market expansion, a different category/mix, or a revised revenue path. It is not established as feasible by this model.</p><p class="micro">${esc(z.interpretation)} ${esc(z.constraints.join(' '))}</p><h3>Separate precision & capital checks</h3><p>The exact platform-growth bridge is 68.5072%; the original 70% judgment adds $909.45m first-year revenue. A separate exact-bridge case gives $403.52 per share versus the preserved $406.98 original. ${esc(d.method2024.capitalMechanism)}</p><p class="micro">${esc(d.method2024.knownCommitments.treatment)} ${esc(d.method2024.shareCountCaveat)}</p>`;}$('#claim-scale-results').innerHTML=html}catch(e){$('#claim-scale-results').textContent=e.message}};
if((location.hash==='#workbench')&&researchCases.some(c=>c.snapshotId==='MSFT-FY2019')&&companies.some(c=>c.snapshots.some(s=>s.raw?.id==='MSFT-FY2019')))$('#open-baseline').click();

function clearCaseDiagnostics(){for(const id of ['research-addenda-results','claim-scale-results'])$('#'+id).innerHTML=''}

for(const target of ['evidence-details','forecast-details'])document.querySelectorAll(`a[href="#${target}"]`).forEach(link=>link.addEventListener('click',()=>{document.getElementById(target).open=true}));

document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();document.querySelector('[data-tab="current"]').click()});
